package com.example.starter.calibration.repository;

import com.example.starter.calibration.domain.Certificate;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 校准证书持久化接口。证书创建后不可修改，只能撤销。
 */
public interface CertificateRepository {

    /**
     * 在同一事务内检查同仪器未撤销证书区间不重叠后插入新证书。
     * 实现必须保证并发调用时重叠证书最多一张成功（行锁/间隙锁或等效机制）。
     *
     * @return 持久化后的证书（含生成的 ID）
     * @throws com.example.starter.calibration.error.ApiException 区间重叠时抛出 409
     */
    Certificate insertIfNoOverlap(Certificate certificate);

    /**
     * 按 ID 查询证书。
     */
    Optional<Certificate> findById(long id);

    /**
     * 按 ID 查询并锁定证书行（SELECT ... FOR UPDATE），用于撤销与放行的串行化。
     */
    Optional<Certificate> findByIdForUpdate(long id);

    /**
     * 撤销证书；仅当存在且未撤销时生效。
     *
     * @return true 表示本次调用完成了撤销
     */
    boolean revoke(long id, Instant revokedAt);

    /**
     * 查找覆盖指定时刻的未撤销证书。区间两两不重叠，因此最多一张。
     */
    Optional<Certificate> findActiveCovering(String instrumentId, Instant instant);

    /**
     * 查询某仪器的全部证书（按有效起点升序）。
     */
    List<Certificate> findByInstrument(String instrumentId);
}

package com.example.starter.calibration.repository;

import com.example.starter.calibration.domain.Measurement;
import java.time.Instant;
import java.util.Collection;
import java.util.List;
import java.util.Optional;

/**
 * 测量记录持久化接口。
 */
public interface MeasurementRepository {

    /**
     * 插入测量记录。measurementKey 重复时抛出 409。
     *
     * @return 持久化后的测量（含生成的 ID）
     */
    Measurement insert(Measurement measurement);

    /**
     * 按 ID 查询测量。
     */
    Optional<Measurement> findById(long id);

    /**
     * 按 ID 查询并锁定测量行（SELECT ... FOR UPDATE）。
     */
    Optional<Measurement> findByIdForUpdate(long id);

    /**
     * 按业务幂等键查询。
     */
    Optional<Measurement> findByMeasurementKey(String measurementKey);

    /**
     * 仅当测量仍处于待放行状态时将其置为已放行（条件更新，保证并发安全）。
     *
     * @return true 表示本次调用完成了状态迁移
     */
    boolean markReleased(long id, String releasedBy, Instant releasedAt);

    /**
     * 按 ID 集合批量查询。
     */
    List<Measurement> findByIds(Collection<Long> ids);

    /**
     * 查询当前可用结果：已放行且其证书未被撤销。instrumentId 为 null 时不过滤。
     */
    List<Measurement> findCurrentUsable(String instrumentId);
}

